#include "xrnkey_internal.h"
#include <string>
#include <unordered_set>
#include <vector>

/* Generated by CMake from data/english.txt and data/vi-syllables.txt (see
 * data/README.md for where the lists come from). */
extern const char* const xrnkey_english_words;
extern const char* const xrnkey_vi_syllables;

namespace xrnkey {

namespace {

/* One entry per line; '#' starts a comment line. */
template <typename F>
void each_line(const char* text, F f) {
    std::string line;
    for (const char* p = text;; ++p) {
        if (*p == '\n' || *p == '\0') {
            while (!line.empty() && (line.back() == '\r' || line.back() == ' ' || line.back() == '\t'))
                line.pop_back();
            if (!line.empty() && line[0] != '#') f(line);
            line.clear();
            if (*p == '\0') break;
        } else {
            line += *p;
        }
    }
}

std::string lower_ascii(const std::string& s) {
    std::string out = s;
    for (char& c : out)
        if (c >= 'A' && c <= 'Z') c = static_cast<char>(c | 0x20);
    return out;
}

/* Tone style does not matter for "is this syllable attested": hòa and hoà are
 * the same syllable, so both sides are reduced to letters + tone number. */
std::string attested_key(const std::u32string& letters, int tone) {
    return utf8_of(letters) + static_cast<char>('0' + tone);
}

/* English as chat writes it, which word lists of edited text leave out: contractions typed
 * without the apostrophe and the commonest abbreviations that have a vowel (those without one
 * are never fixed anyway). They are words as they stand, as Laban Key keeps them: Space used to
 * "fix" "youre" into "your", "isnt" into "isn" and "rofl" into "roll", and "didnt" ended as
 * "đint". None of them is a Vietnamese syllable. */
constexpr const char* kChatEnglish[] = {
    "aint", "arent", "couldnt", "didnt", "doesnt", "dont", "hadnt", "hasnt", "havent", "heres",
    "hows", "isnt", "itll", "ive", "mustnt", "neednt", "shes", "shouldnt", "thatll", "thats",
    "theres", "theyd", "theyll", "theyre", "theyve", "wasnt", "werent", "weve", "whats",
    "wheres", "whos", "wouldnt", "yall", "youd", "youll", "youre", "youve",
    "abt", "afaik", "asap", "bae", "bday", "coz", "cuz", "cya", "fomo", "fyi", "hbu", "idc",
    "idk", "iirc", "ikr", "ily", "imho", "imo", "irl", "lmao", "lol", "nah", "ofc", "okie", "omg",
    "omw", "otw", "rofl", "sus", "wbu", "wyd", "xoxo", "yolo", "yup",
};

const std::unordered_set<std::string>& english() {
    static const std::unordered_set<std::string> set = [] {
        std::unordered_set<std::string> s;
        each_line(xrnkey_english_words, [&](const std::string& w) { s.insert(lower_ascii(w)); });
        for (const char* w : kChatEnglish) s.insert(w);
        return s;
    }();
    return set;
}

const std::unordered_set<std::string>& attested() {
    static const std::unordered_set<std::string> set = [] {
        std::unordered_set<std::string> s;
        each_line(xrnkey_vi_syllables, [&](const std::string& w) {
            std::u32string letters;
            int tone;
            if (syllable_split(w, &letters, &tone)) s.insert(attested_key(letters, tone));
        });
        return s;
    }();
    return set;
}

}  // namespace

const std::vector<std::string>& lexicon_attested_words() {
    static const std::vector<std::string> words = [] {
        std::vector<std::string> v;
        each_line(xrnkey_vi_syllables, [&](const std::string& w) { v.push_back(w); });
        return v;
    }();
    return words;
}

bool lexicon_is_english(const std::string& word) {
    return english().count(lower_ascii(word)) > 0;
}

bool lexicon_is_attested(const std::u32string& letters, int tone) {
    return attested().count(attested_key(letters, tone)) > 0;
}

} /* namespace xrnkey */
